module counter_assertions #(parameter W = 4) (
    input wire clk,
    input wire rst,
    input wire en,
    input wire [W-1:0] cnt
);

    // Property: Counter must increment by exactly 1 when enabled.
    // Ensures no skipping or jumping occurs during active cycles.
    property p_cnt_increment;
        @(posedge clk) disable iff (rst)
            en |-> (cnt == $past(cnt) + 1'b1);
    endproperty

    // Property: Counter must hold value when disabled.
    // Ensures no unintended state changes occur when not enabled.
    property p_cnt_hold;
        @(posedge clk) disable iff (rst)
            !en |-> (cnt == $past(cnt));
    endproperty

    // Assertion: Enforce increment behavior
    ap_cnt_increment: assert property (p_cnt_increment);

    // Assertion: Enforce hold behavior
    ap_cnt_hold: assert property (p_cnt_hold);

endmodule
```

