module rr_arbiter_assertions #(parameter N = 4) (
    input  wire         clk,
    input  wire         rst,
    input  wire [N-1:0] req,
    input  wire [N-1:0] grant
);

    property p_onehot_or_zero;
        @(posedge clk) $onehot0(grant);
    endproperty

    property p_grant_subset_req;
        @(posedge clk) (grant & ~req) == 0;
    endproperty

    assert property (p_onehot_or_zero);
    assert property (p_grant_subset_req);

endmodule
